    opp_d = n - opp_c
    my_c = sum(1 for a, b in history if a == 'C')
    my_d = n - my_c

    if n < 5:
        return 'C'

    if n >= 95:
        if opp_d <= 2 and my_d <= 2:
            return 'C'
        if opp_prev == 'D' and opp_d >= 5:
            return 'D'
        if opp_prev == 'D':
            return 'C'
        if opp_d > my_d + 2:
            return 'D'
        return 'C'

    if n >= 80:
        if opp_d <= 3:
            return 'C'
        if opp_prev == 'D' and opp_d >= 8:
            return 'D'
        if opp_d * 3 > n * 2:
            return 'D'
        return 'C'

    if n < 10:
        return 'C'

    # detect always defect / high defection
    if opp_d >= n - 2 and n >= 8:
        return 'D'

    # detect always cooperate
